import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BUOFcz_J.js";const u=JSON.parse('{"title":"Install and open a project","description":"","frontmatter":{},"headers":[],"relativePath":"start/index.md","filePath":"start/index.md"}'),i={name:"start/index.md"};function n(r,e,h,d,l,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="install-and-open-a-project" tabindex="-1">Install and open a project <a class="header-anchor" href="#install-and-open-a-project" aria-label="Permalink to &quot;Install and open a project&quot;">​</a></h1><p>Rho is a local service with a WebUI. It runs on your machine, in a folder you choose, and it talks to an Agent client you already have. Nothing is sent to a Rho server, because there is no Rho server.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>What Rho needs</th></tr></thead><tbody><tr><td>Node</td><td><code>&gt;=22.22.0 &lt;27</code>: the 22, 24 and 26 LTS lines. The checked baseline is Node 22.22.3 with npm 10.9.8; the test suite and the installed check also passed on 24.22.2 and 26.13.0.</td></tr><tr><td>R</td><td>Only for R work. The service, documents, readers and saved results work without R; a missing <code>Rscript</code> reports an unknown dependency probe instead of pretending.</td></tr><tr><td>R packages</td><td>Yours to install. Rho does not install project packages implicitly.</td></tr><tr><td>Agent client</td><td>Claude Code or Codex, installed and signed in by you. Conversations drive your client under your own permissions.</td></tr><tr><td>Python</td><td>Only for the file writer lock on platforms that need it. Windows does not.</td></tr></tbody></table><p>macOS arm64 is the checked baseline. Windows x64 was checked with Node 22.23.4 and Rscript 4.5.1; Linux x64 and arm64 carry platform installs. On macOS x64 the application starts only under Rosetta.</p><h2 id="or-ask-your-agent" tabindex="-1">Or ask your Agent <a class="header-anchor" href="#or-ask-your-agent" aria-label="Permalink to &quot;Or ask your Agent&quot;">​</a></h2><p>Paste this into Claude Code or Codex:</p><blockquote><p>Read <a href="https://yulab-smu.top/Rho/doc/setup.md" target="_blank" rel="noreferrer">https://yulab-smu.top/Rho/doc/setup.md</a> and follow its steps to install and configure Rho for me.</p></blockquote><p>The <a href="https://yulab-smu.top/Rho/doc/setup.md" target="_blank" rel="noreferrer">setup page</a> holds every command, so you can read it first. Your Agent checks the requirements above and looks for a Rho that is already there, then installs the package, starts Rho on <code>~/Rho/projects</code> and <code>~/Rho/state</code>, adds the Rho Skill to its own skills folder, connects itself to the example project and tells you what is missing.</p><h2 id="install-from-npm" tabindex="-1">Install from npm <a class="header-anchor" href="#install-from-npm" aria-label="Permalink to &quot;Install from npm&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#6F42C1;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> @rho-workspace/rho</span></span></code></pre></div><p>If the global prefix belongs to root, this fails with <code>EACCES</code>; installing it with <code>sudo</code> was performed and worked. The package declares its Node range, so a Node outside it prints one <code>EBADENGINE</code> warning rather than failing silently.</p><h2 id="start-the-service" tabindex="-1">Start the service <a class="header-anchor" href="#start-the-service" aria-label="Permalink to &quot;Start the service&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#6F42C1;">rho</span></span></code></pre></div><p>From 0.5.4, <code>rho</code> with no arguments uses <code>~/Rho/projects</code> and <code>~/Rho/state</code>. It creates both, copies the example project into a new state, and prints the address to open, the two folders and whether your Agent client and R were found. 0.5.3 prints its usage instead. To choose the folders yourself, on any version:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#6F42C1;">rho</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> /absolute/projects</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> --state-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> /absolute/service-state</span></span></code></pre></div><p>Create the projects directory first. Keep service state outside it, so a project stays an ordinary folder. Startup prints the loopback URL and the location of the connection file — never the credential. Opening that URL in a browser on the same machine is the access: a same-origin request from loopback is answered as the local person, with no link, no code and no expiry.</p><p>A one-time link is available when a tab must be narrower or must expire:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#6F42C1;">rho</span><span style="--shiki-light:#005CC5;--shiki-dark:#005CC5;"> --pair</span></span></code></pre></div><p>That link is a credential with a five-minute window and a single use.</p><h2 id="open-the-example-project" tabindex="-1">Open the example project <a class="header-anchor" href="#open-the-example-project" aria-label="Permalink to &quot;Open the example project&quot;">​</a></h2><p>A new state copies the bundled <code>example/pa14-qs</code> project into your projects folder once, as an ordinary editable project. Open it, then ask the Agent a question about one of its figures or a selected row of a result table.</p><h2 id="what-to-read-next" tabindex="-1">What to read next <a class="header-anchor" href="#what-to-read-next" aria-label="Permalink to &quot;What to read next&quot;">​</a></h2><ul><li><a href="/Rho/docs/reference/headless">Headless backend</a> — HTTP, SSE, Agent adapters, persistence and budgets.</li><li><a href="/Rho/docs/concepts/architecture">Architecture</a> — which repository owns what.</li><li><a href="/Rho/docs/reference/status">Status</a> — what has been checked, what is limited, and what remains open.</li><li><a href="/Rho/docs/records/ci-episode">Troubleshooting by evidence</a> — the CI episode records the install failures that were actually hit, with the fix that worked.</li></ul>',24)])])}const k=t(i,[["render",n]]);export{u as __pageData,k as default};
